"""Official ETEC Nafes English Grade 9 (Intermediate, CEFR B1) Question Bank: 360 unique 4-option MCQs across 24 blueprints."""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from nafes_ext_common import (
    make_english_q,
    svg_idea_map,
    svg_reading_card,
    svg_sequence_strip,
    svg_tense_timeline,
    svg_word_morphology,
    wrap_passage_box,
)


def _diff(idx: int) -> str:
    return "Easy" if idx < 5 else ("Medium" if idx < 10 else "Hard")


def build_g9_english_bank() -> list[dict]:
    qs: list[dict] = []
    qnum = 1

    def add(bp: str, topic: str, idx: int, q_en: str, q_ar: str, opts: list[str], h_en: str, h_ar: str,
            i_en: str, s_en: list[str], c_en: str, i_ar: str, s_ar: list[str], c_ar: str, diagram: str = None):
        nonlocal qnum
        qid = f"NAFS-ENG-G9-{qnum:03d}"
        qnum += 1
        qs.append(make_english_q(
            qid=qid, level="English · Grade 9", topic=topic, difficulty=_diff(idx), blueprint=bp,
            q_en=q_en, q_ar=q_ar, options=opts, hint_en=h_en, hint_ar=h_ar,
            idea_en=i_en, steps_en=s_en, check_en=c_en, idea_ar=i_ar, steps_ar=s_ar, check_ar=c_ar,
            diagram_en=diagram, diagram_ar=diagram,
        ))

    # =========================================================================
    # READING COMPREHENSION (G9-ENG-B01 .. G9-ENG-B06)
    # =========================================================================

    # B01: Academic & Saudi Vision 2030 / STEM passage synthesis
